def simulate_natural_selection(population, generations, mutation_rate):
    import random

    def calculate_fitness(population):
        total_fitness = sum(population)
        return [individual / total_fitness for individual in population]

    def select_survivors(population, fitness):
        cumulative_fitness = sum(fitness)
        survivors = []
        for individual, fitness in zip(population, fitness):
            r = random.random() * cumulative_fitness
            if r < fitness:
                survivors.append(individual)
                cumulative_fitness -= fitness
            else:
                continue
        return survivors

    def apply_mutation(individual):
        if random.random() < mutation_rate:
            return individual + random.choice([-1, 1])
        else:
            return individual

    population = population.copy()
    for _ in range(generations):
        fitness = calculate_fitness(population)
        survivors = select_survivors(population, fitness)
        mutated_survivors = [apply_mutation(individual) for individual in survivors]
        population = mutated_survivors

    return population

