struct Habit {
    @objc property NSString *name;
    @objc property BOOL isDaily;
    @objc property NSString *completionMessage;
};

class HabitStore {
    @property array<Habit> habits;
    @property array<Habit> dailyHabits;
    @property array<array<Habit>> history;

    - (void)addHabit:(NSString *)name isDaily:(BOOL)isDaily completionMessage:(NSString *)message {
        Habit *habit = [[Habit alloc] initWithName:name isDaily:isDaily completionMessage:completionMessage];
        self.habits = [self.habits arrayWithObject:habit];
        if (isDaily) {
            self.dailyHabits = [self.dailyHabits arrayWithObject:habit];
        }
    }

    - (void)markHabitCompleted:(Habit *)habit {
        [self.dailyHabits removeObject:habit];
        NSMutableArray *historyEntry = [NSMutableArray array];
        [self.dailyHabits addObject:historyEntry];
        [self.history addObject:historyEntry];
        self.dailyHabits = @[]
    }
};
